        getPerformanceSummary(history) {
            if (!history.length) return {};
            var revpars = history.map(function(r) { return r.results ? (r.results.revpar || 0) : 0; });
            var totalRevPAR = revpars.reduce(function(s, v) { return s + v; }, 0);
            var avgRevPAR = totalRevPAR / revpars.length;
            var cris = history.map(function(r) { return r.results ? (r.results.cri || 0) : 0; });
            var avgCRI = cris.reduce(function(s, v) { return s + v; }, 0) / cris.length;
            var lastResult = history[history.length - 1];
            var finalGSS = lastResult && lastResult.results ? (lastResult.results.gss || 85) : 85;
            var walkTotal = history.reduce(function(s, r) { return s + (r.results ? (r.results.walkCount || 0) : 0); }, 0);

            // the bands read the score the student sees (the rounded avg CRI), so a displayed 88 is never graded below 88
            var _sc = Math.round(avgCRI);
            var performance = 'Principiante';
            var insights = [];
            if (_sc >= 88 && finalGSS >= 80 && walkTotal === 0) {
                performance = 'Excelente — Revenue Manager Estratégico';
                insights = ['Excelente balance entre RevPAR, Net RevPAR y satisfacción de huéspedes.', 'Superaste al conjunto competitivo en la mayoría de las temporadas.'];
            } else if (_sc >= 72) {
                performance = 'Competente — Gestor de Yield Sólido';
                insights = ['Buen desempeño general. Revisa la asignación de inventario y el mix de canales para mejorar el Net RevPAR.'];
            } else {
                performance = 'En Desarrollo — Revenue Management Básico';
                insights = ['Considera estrategias de protección de inventario y evita la dependencia excesiva de OTAs.', 'Recuerda: RevPAR = ADR x Ocupación. Equilibrar ambas es clave.'];
            }
            if (walkTotal > 3) {
                insights.push('Los eventos de walk daniaron el GSS. Calibra el overbooking según la tasa de no-show del periodo.');
            }

            // v1.1.2 bands: the top tier needs avg CRI 88 (the case options score 84-85, random play 71-80 at p10-p90
            // with median 77 since the v1.1.3 business-rate response),
            // the middle tier 72; a final GSS of 80 and zero walks still gate the top tier
            var _tier = (_sc >= 88 && finalGSS >= 80 && walkTotal === 0) ? 'excellent'
                      : (_sc >= 72) ? 'competent' : 'developing';
            var _tt = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var _performanceLabel = _tt('grade_' + _tier);
            var _locIns = (_tier === 'excellent') ? [_tt('insight_exc_1'), _tt('insight_exc_2')]
                        : (_tier === 'competent') ? [_tt('insight_comp_1')]
                        : [_tt('insight_dev_1'), _tt('insight_dev_2')];
            if (walkTotal > 3) { _locIns.push(_tt('insight_walk')); }
            insights = _locIns;
            var _overall = Math.round(avgCRI);
            return {
                avgRevPAR: avgRevPAR,
                avgCRI: avgCRI,
                overallScore: _overall,
                score: _overall,
                finalGSS: finalGSS,
                walkTotal: walkTotal,
                performance: performance,
                performanceLabel: _performanceLabel,
                tier: _tier,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (results.walkCount > 2) return t('hint_walk');
            if (results.occupancyRate < 55) return t('hint_low_occ');
            if (results.occupancyRate >= 95 && state.domainState.gss >= 80) return t('hint_full_house');
            if (results.rgi && results.rgi < 0.85) return t('hint_low_rgi');
            return null;
        }

