        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            function L(k, f) { var v = self._t(k); return v || f; }
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var verdict = summary.performanceLabel || summary.performance || '';
            var met = score >= 72;
            var badge = met ? L('cm_pass', 'Target met') : L('cm_below', 'Below target');
            var badgeClass = met ? 'hpac-cm-pass' : 'hpac-cm-below';
            var avgRevPAR = summary.avgRevPAR || 0;
            var finalGSS = summary.finalGSS || 0;
            var walks = summary.walkTotal || 0;
            function money(v) { return '$' + (Math.round((v || 0) * 100) / 100).toLocaleString(); }
            var kpis = '' +
                '<div class="hpac-cm-kpi"><span class="hpac-cm-kpi-v">' + money(avgRevPAR) + '</span><span class="hpac-cm-kpi-l">' + L('cm_kpi_revpar', 'Avg RevPAR') + '</span></div>' +
                '<div class="hpac-cm-kpi"><span class="hpac-cm-kpi-v">' + score + '</span><span class="hpac-cm-kpi-l">' + L('cm_kpi_score', 'CRI score') + '</span></div>' +
                '<div class="hpac-cm-kpi"><span class="hpac-cm-kpi-v">' + Math.round(finalGSS) + '</span><span class="hpac-cm-kpi-l">' + L('cm_kpi_gss', 'Final GSS') + '</span></div>' +
                '<div class="hpac-cm-kpi"><span class="hpac-cm-kpi-v">' + walks + '</span><span class="hpac-cm-kpi-l">' + L('cm_kpi_walks', 'Walk events') + '</span></div>';
            var insights = summary.insights || [];
            var insHtml = '';
            if (insights.length) { insHtml = '<ul class="hpac-cm-insights">'; for (var i = 0; i < insights.length; i++) { insHtml += '<li>' + insights[i] + '</li>'; } insHtml += '</ul>'; }
            return '' +
                '<div class="hpac-cm">' +
                    '<div class="hpac-cm-head">' + L('cm_title', 'Revenue Debrief') + '</div>' +
                    '<div class="hpac-cm-score">' + score + '<span class="hpac-cm-score-max">/100</span></div>' +
                    '<div class="hpac-cm-verdict">' + verdict + ' <span class="hpac-cm-badge ' + badgeClass + '">' + badge + '</span></div>' +
                    '<div class="hpac-cm-kpis">' + kpis + '</div>' +
                    (insHtml ? '<div class="hpac-cm-insights-h">' + L('cm_insights', 'Key insights') + '</div>' + insHtml : '') +
                '</div>';
        }

        getTranslations() {
            return {
                en: {
