        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            if (!round) return;

            var lang = (document.documentElement.lang || 'es').toLowerCase().substring(0, 2);
            var isEs = lang !== 'en';

            var scenarioEl = document.getElementById('scenarioName');
            if (scenarioEl) scenarioEl.textContent = isEs ? round.scenarioName_es : round.scenarioName_en;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = isEs ? round.briefing_es : round.briefing_en;

            var metEl = document.getElementById('rateMetropolis');
            var conEl = document.getElementById('rateConecta');
            var suitEl = document.getElementById('rateSuites');
            if (metEl) metEl.textContent = '$' + round.compRates.metropolis;
            if (conEl) conEl.textContent = '$' + round.compRates.conecta;
            if (suitEl) suitEl.textContent = '$' + round.compRates.suites;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new HotelPacificoAdapter(), {
            simulationType: 'hotel_pacifico_rm',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
    });

